import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_false_on_runner():
    @click.command()
    def cli_raises():
        raise ValueError("This is an error")

    runner = CliRunner(catch_exceptions=False)
    with pytest.raises(ValueError, match="This is an error"):
        runner.invoke(cli_raises)

import pytest
import click
from click.testing import CliRunner


class MyClass:
    def __init__(self, myvalue: str) -> None:
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str!r}, should be 'works'")
        return MyClass(input_str)


@pytest.fixture
def runner():
    return CliRunner()


def test_func_param_type_value_error_message(runner):
    @click.command()
    @click.argument("mydata", type=MyClass.from_str)
    def cli(mydata):
        click.echo(f"Success: {mydata.myvalue}")

    result = runner.invoke(cli, ["fails"])
    assert "Error: input was 'fails', should be 'works'" in result.output
